config.script:
members = ['BeanName', 'Origin', 'Region', 'Farm', 'Altitude', 'Variety', 'Process', 'HarvestYear', 'MoisturePct', 'DensityGL', 'ChargeWeightG', 'TargetDropTempF', 'RoastLevel', 'OperatorName', 'Notes', 'WeightOutG']
base = '[default]Roastery/CurrentBatch'
try:
	q = system.tag.readBlocking([base + '/' + m for m in members])
	ints = ('HarvestYear',)
	floats = ('MoisturePct', 'DensityGL', 'ChargeWeightG', 'TargetDropTempF', 'WeightOutG')
	data = {}
	for i in range(len(members)):
		v = q[i].value
		if members[i] in ints:
			data[members[i]] = int(v) if v is not None else 0
		elif members[i] in floats:
			data[members[i]] = float(v) if v is not None else 0.0
		else:
			data[members[i]] = v if v is not None else ''
	self.getChild('root').getChild('MetaForm').props.data = data
except Exception:
	pass

members = ('BeanName', 'Origin', 'Region', 'Farm', 'Altitude', 'Variety', 'Process', 'HarvestYear', 'MoisturePct', 'DensityGL', 'ChargeWeightG', 'TargetDropTempF', 'RoastLevel', 'OperatorName', 'Notes', 'WeightOutG')
ints = ('HarvestYear',)
floats = ('MoisturePct', 'DensityGL', 'ChargeWeightG', 'TargetDropTempF', 'WeightOutG')
base = '[default]Roastery/CurrentBatch'
paths = []
values = []
for k in members:
	if k not in event:
		continue
	v = event[k]
	if v is None:
		continue
	try:
		if k in ints:
			v = int(float(v))
		elif k in floats:
			v = float(v)
		else:
			v = str(v)
	except Exception:
		continue
	paths.append(base + '/' + k)
	values.append(v)
if paths:
	system.tag.writeBlocking(paths, values)
	self.view.custom.formSaved = 'Batch details saved.'
